 31→func newAttachCmd() *cobra.Command {
 32→	var (
 33→		force     bool
 34→		agentFlag string
 35→	)
 36→	cmd := &cobra.Command{
 37→		Use:   "attach <session-id>",
 38→		Short: "Attach an existing agent session",
 39→		Long: `Attach an existing agent session that wasn't captured by hooks.
 40→
 41→This creates a checkpoint from the session's transcript and registers the
 42→session for future tracking. Use this when hooks failed to fire or weren't
 43→installed when the session started.
 44→
 45→Supported agents: claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid`,
 46→		Args: cobra.ExactArgs(1),
 47→		RunE: func(cmd *cobra.Command, args []string) error {
 48→			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
 49→				return nil
 50→			}
 51→			agentName := types.AgentName(agentFlag)
 52→			return runAttach(cmd.Context(), cmd.OutOrStdout(), args[0], agentName, force)
 53→		},
 54→	}
 55→	cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmation and amend the last commit with the checkpoint trailer")
 56→	cmd.Flags().StringVarP(&agentFlag, "agent", "a", string(agent.DefaultAgentName), "Agent that created the session (claude-code, gemini, opencode, cursor, copilot-cli, factoryai-droid)")
 57→	return cmd
 58→}
 59→
 60→func runAttach(ctx context.Context, w io.Writer, sessionID string, agentName types.AgentName, force bool) error {
 61→	logCtx := logging.WithComponent(ctx, "attach")
 62→
 63→	// Validate session ID format
 64→	if err := validation.ValidateSessionID(sessionID); err != nil {
 65→		return fmt.Errorf("invalid session ID: %w", err)
 66→	}
 67→
 68→	// Ensure we're in a git repo
 69→	repoRoot, err := paths.WorktreeRoot(ctx)
 70→	if err != nil {
 71→		return fmt.Errorf("not a git repository: %w", err)
 72→	}
 73→
 74→	// Check session isn't already tracked
 75→	store, err := session.NewStateStore(ctx)
 76→	if err != nil {
 77→		return fmt.Errorf("failed to open session store: %w", err)
 78→	}
 79→	existing, err := store.Load(ctx, sessionID)
 80→	if err != nil {
 81→		return fmt.Errorf("failed to check existing session: %w", err)
 82→	}
 83→	if existing != nil {
 84→		return fmt.Errorf("session %s is already tracked by Entire", sessionID)
 85→	}
 86→
 87→	// Resolve agent and transcript path
 88→	ag, err := agent.Get(agentName)
 89→	if err != nil {
 90→		return fmt.Errorf("agent %q not available: %w", agentName, err)
 91→	}
 92→	agentType := ag.Type()
 93→
 94→	transcriptPath, err := resolveAndValidateTranscript(logCtx, sessionID, agentName, ag)
 95→	if err != nil {
 96→		return err
 97→	}
 98→
 99→	// Read transcript data
100→	transcriptData, err := ag.ReadTranscript(transcriptPath)
101→	if err != nil {
102→		return fmt.Errorf("failed to read transcript: %w", err)
103→	}
104→
105→	// Extract modified files from transcript
106→	var modifiedFiles []string
107→	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
108→		if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptPath, 0); fileErr != nil {
109→			logging.Warn(logCtx, "failed to extract modified files from transcript", "error", fileErr)
110→		} else {
111→			modifiedFiles = files
112→		}
113→	}
114→
115→	// Detect file changes via git status (no pre-untracked filter since we don't know pre-state)
116→	changes, err := DetectFileChanges(ctx, nil)
117→	if err != nil {
118→		logging.Warn(logCtx, "failed to detect file changes, checkpoint may be incomplete", "error", err)
119→	}
120→
121→	// Filter and normalize paths
122→	relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
123→	var relNewFiles, relDeletedFiles []string
124→	if changes != nil {
125→		relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
126→		relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
127→		relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
128→	}
129→
130→	// Filter to uncommitted files only
131→	relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
132→
133→	if err := strategy.EnsureSetup(ctx); err != nil {
134→		return fmt.Errorf("failed to set up strategy: %w", err)
135→	}
136→
137→	// Create session metadata directory and copy transcript
138→	sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
139→	sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
140→	if err != nil {
141→		return fmt.Errorf("failed to resolve session directory path: %w", err)
142→	}
143→	if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
144→		return fmt.Errorf("failed to create session directory: %w", err)
145→	}
146→	// Normalize Gemini transcripts so the content field is a plain string
147→	// (Gemini user messages use [{"text":"..."}] arrays, which the UI can't render).
148→	storedTranscript := transcriptData
149→	if agentType == agent.AgentTypeGemini {
150→		if normalized, normErr := normalizeGeminiTranscript(transcriptData); normErr == nil {
151→			storedTranscript = normalized
152→		} else {
153→			logging.Warn(logCtx, "failed to normalize Gemini transcript, storing raw", "error", normErr)
154→		}
155→	}
156→	logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
157→	if err := os.WriteFile(logFile, storedTranscript, 0o600); err != nil {
158→		return fmt.Errorf("failed to write transcript: %w", err)
159→	}
160→
161→	// Get git author
162→	author, err := GetGitAuthor(ctx)
163→	if err != nil {
164→		return fmt.Errorf("failed to get git author: %w", err)
165→	}
166→
167→	// Extract first prompt from transcript for the commit message
168→	firstPrompt := extractFirstPromptFromTranscript(transcriptData)
169→	commitMessage := generateCommitMessage(firstPrompt, agentType)
170→
171→	// Write prompt.txt so SaveStep includes it on the shadow branch
172→	// and CondenseSession can read it for the checkpoint metadata.
173→	if firstPrompt != "" {
174→		promptFile := filepath.Join(sessionDirAbs, paths.PromptFileName)
175→		if err := os.WriteFile(promptFile, []byte(firstPrompt), 0o600); err != nil {
176→			logging.Warn(logCtx, "failed to write prompt file", "error", err)
177→		}
178→	}
179→
180→	// Initialize session state BEFORE SaveStep so it exists when SaveStep loads it
181→	strat := GetStrategy(ctx)
182→	if err := strat.InitializeSession(ctx, sessionID, agentType, transcriptPath, firstPrompt, ""); err != nil {
183→		return fmt.Errorf("failed to initialize session: %w", err)
184→	}
185→
186→	// Enrich session state with transcript-derived metadata
187→	if err := enrichSessionState(logCtx, sessionID, ag, transcriptData, transcriptPath); err != nil {
188→		return err
189→	}
190→
191→	// Build step context and save checkpoint
192→	totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
193→
194→	stepCtx := strategy.StepContext{
195→		SessionID:      sessionID,
196→		ModifiedFiles:  relModifiedFiles,
197→		NewFiles:       relNewFiles,
198→		DeletedFiles:   relDeletedFiles,
199→		MetadataDir:    sessionDir,
200→		MetadataDirAbs: sessionDirAbs,
201→		CommitMessage:  commitMessage,
202→		TranscriptPath: transcriptPath,
203→		AuthorName:     author.Name,
204→		AuthorEmail:    author.Email,
205→		AgentType:      agentType,
206→	}
207→
208→	if err := strat.SaveStep(ctx, stepCtx); err != nil {
209→		return fmt.Errorf("failed to save checkpoint: %w", err)
210→	}
211→
212→	checkpointIDStr, condenseErr := condenseAndFinalizeSession(logCtx, strat, sessionID)
213→
214→	// Print confirmation
215→	fmt.Fprintf(w, "Attached session %s\n", sessionID)
216→	if totalChanges > 0 {
217→		fmt.Fprintf(w, "  Checkpoint saved with %d file(s)\n", totalChanges)
218→	} else {
219→		fmt.Fprintln(w, "  Checkpoint saved (transcript only, no uncommitted file changes detected)")
220→	}
221→	if condenseErr != nil {
222→		fmt.Fprintln(w, "  Warning: checkpoint saved on shadow branch only (condensation failed)")
223→	}
224→	fmt.Fprintln(w, "  Session is now tracked — future prompts will be captured automatically")
225→
226→	// Offer to amend the last commit with the checkpoint trailer
227→	if checkpointIDStr != "" {
228→		if err := promptAmendCommit(ctx, w, checkpointIDStr, force); err != nil {
229→			logging.Warn(logCtx, "failed to amend commit", "error", err)
230→			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
231→		}
232→	}
233→
234→	return nil
235→}
236→
237→// enrichSessionState loads the session state after initialization and populates it with
238→// transcript-derived metadata (token usage, turn count, model name, duration).
239→func enrichSessionState(ctx context.Context, sessionID string, ag agent.Agent, transcriptData []byte, transcriptPath string) error {
240→	state, err := strategy.LoadSessionState(ctx, sessionID)
241→	if err != nil {
242→		return fmt.Errorf("failed to load session state: %w", err)
243→	}
244→	if state == nil {
245→		return fmt.Errorf("session state not found after initialization (session_id=%s)", sessionID)
246→	}
247→	state.CLIVersion = versioninfo.Version
248→	state.TranscriptPath = transcriptPath
249→
250→	if usage := agent.CalculateTokenUsage(ctx, ag, transcriptData, 0, ""); usage != nil {
251→		state.TokenUsage = usage
252→	}
253→	if turns := countUserTurns(transcriptData); turns > 0 {
254→		state.SessionTurnCount = turns
255→	}
256→	if model := extractModelFromTranscript(transcriptData); model != "" {
257→		state.ModelName = model
258→	}
259→	if dur := estimateSessionDuration(transcriptData); dur > 0 {
260→		state.SessionDurationMs = dur
261→	}
262→
263→	if err := strategy.SaveSessionState(ctx, state); err != nil {
264→		return fmt.Errorf("failed to save session state: %w", err)
265→	}
266→	return nil
267→}
268→
269→// condenseAndFinalizeSession condenses the session to permanent storage and transitions it to IDLE.
270→// Returns the checkpoint ID string and any condensation error.
271→func condenseAndFinalizeSession(ctx context.Context, strat *strategy.ManualCommitStrategy, sessionID string) (string, error) {
272→	var checkpointIDStr string
273→	var condenseErr error
274→	if err := strat.CondenseSessionByID(ctx, sessionID); err != nil {
275→		logging.Warn(ctx, "failed to condense session", "error", err, "session_id", sessionID)
276→		condenseErr = err
277→	}
278→
279→	// Single load serves both checkpoint ID extraction and finalization
280→	state, loadErr := strategy.LoadSessionState(ctx, sessionID)
281→	if loadErr != nil {
282→		logging.Warn(ctx, "failed to load session state after condensation", "error", loadErr, "session_id", sessionID)
283→		return checkpointIDStr, condenseErr
284→	}
285→	if state == nil {
286→		return checkpointIDStr, condenseErr
287→	}
288→
289→	if condenseErr == nil {
290→		checkpointIDStr = state.LastCheckpointID.String()
291→	}
292→
293→	now := time.Now()
294→	state.LastInteractionTime = &now
295→	if transErr := strategy.TransitionAndLog(ctx, state, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
296→		logging.Warn(ctx, "failed to transition session to idle", "error", transErr, "session_id", sessionID)
297→	}
298→	if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
299→		logging.Warn(ctx, "failed to save session state after transition", "error", saveErr, "session_id", sessionID)
300→	}
301→
302→	return checkpointIDStr, condenseErr
303→}
304→
305→// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
306→// project directories if needed.
307→func resolveAndValidateTranscript(ctx context.Context, sessionID string, agentName types.AgentName, ag agent.Agent) (string, error) {
308→	transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
309→	if err != nil {
310→		return "", fmt.Errorf("failed to resolve transcript path: %w", err)
311→	}
312→	// Agents use cwd-derived project directories, so the transcript may be stored under
313→	// a different project directory if the session was started from a different working directory.
314→	if _, statErr := os.Stat(transcriptPath); statErr == nil {
315→		return transcriptPath, nil
316→	}
317→	found, searchErr := searchTranscriptInProjectDirs(agentName, sessionID, ag)
318→	if searchErr == nil {
319→		logging.Info(ctx, "found transcript in alternative project directory", "path", found)
320→		return found, nil
321→	}
322→	logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
323→	return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", agentName, sessionID)
324→}
325→
326→// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
327→// When force is true, it amends without prompting.
328→func promptAmendCommit(ctx context.Context, w io.Writer, checkpointIDStr string, force bool) error {
329→	// Get HEAD commit info
330→	repo, err := openRepository(ctx)
331→	if err != nil {
332→		return fmt.Errorf("failed to open repository: %w", err)
333→	}
334→	headRef, err := repo.Head()
335→	if err != nil {
336→		return fmt.Errorf("failed to get HEAD: %w", err)
337→	}
338→	headCommit, err := repo.CommitObject(headRef.Hash())
339→	if err != nil {
340→		return fmt.Errorf("failed to get HEAD commit: %w", err)
341→	}
342→
343→	shortHash := headRef.Hash().String()[:7]
344→	subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
345→
346→	fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
347→
348→	amend := true
349→	if !force {
350→		form := NewAccessibleForm(
351→			huh.NewGroup(
352→				huh.NewConfirm().
353→					Title("Amend the last commit in this branch?").
354→					Affirmative("Y").
355→					Negative("n").
356→					Value(&amend),
357→			),
358→		)
359→		if err := form.Run(); err != nil {
360→			return fmt.Errorf("prompt failed: %w", err)
361→		}
362→	}
363→
364→	if !amend {
365→		fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
366→		return nil
367→	}
368→
369→	// Amend the commit with the checkpoint trailer.
370→	// If the message already has trailers, append on a new line; otherwise add a blank line first.
371→	trimmed := strings.TrimRight(headCommit.Message, "\n")
372→	trailer := fmt.Sprintf("%s: %s", trailers.CheckpointTrailerKey, checkpointIDStr)
373→	var newMessage string
374→	if _, found := trailers.ParseCheckpoint(headCommit.Message); found {
375→		// Already has at least one Entire-Checkpoint trailer — append directly
376→		newMessage = fmt.Sprintf("%s\n%s\n", trimmed, trailer)
377→	} else {
378→		newMessage = fmt.Sprintf("%s\n\n%s\n", trimmed, trailer)
379→	}
380→
381→	cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "-m", newMessage)
382→	if output, err := cmd.CombinedOutput(); err != nil {
383→		return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
384→	}
385→
386→	fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
387→	return nil
388→}
389→
390→// extractFirstPromptFromTranscript reads transcript bytes and returns the first user prompt.
391→// Supports both JSONL format (Claude Code, Cursor, OpenCode) and Gemini JSON format.
392→func extractFirstPromptFromTranscript(data []byte) string {
393→	// Try JSONL format first (Claude Code, Cursor, OpenCode, etc.)
394→	lines, err := transcript.ParseFromBytes(data)
395→	if err == nil {
396→		for _, line := range lines {
397→			if line.Type == transcript.TypeUser {
398→				if prompt := transcript.ExtractUserContent(line.Message); prompt != "" {
399→					return prompt
400→				}
401→			}
402→		}
403→	}
404→
405→	// Fallback: try Gemini JSON format {"messages": [...]}
406→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil && len(prompts) > 0 {
407→		return prompts[0]
408→	}
409→
410→	return ""
411→}
412→
413→// normalizeGeminiTranscript re-serializes a Gemini JSON transcript so that all
414→// content fields are plain strings. Gemini user messages store content as
415→// [{"text":"..."}] arrays, but the UI expects string content. Parsing through
416→// geminicli.ParseTranscript normalizes this via GeminiMessage.UnmarshalJSON.
417→func normalizeGeminiTranscript(data []byte) ([]byte, error) {
418→	parsed, err := geminicli.ParseTranscript(data)
419→	if err != nil {
420→		return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
421→	}
422→	normalized, err := json.MarshalIndent(parsed, "", "  ")
423→	if err != nil {
424→		return nil, fmt.Errorf("failed to re-serialize Gemini transcript: %w", err)
425→	}
426→	return normalized, nil
427→}
428→
429→// countUserTurns counts real user prompts in a transcript (excluding tool_result messages).
430→// Supports both JSONL format (Claude Code, Cursor) and Gemini JSON format.
431→func countUserTurns(data []byte) int {
432→	// Try JSONL format first — use ExtractUserContent to distinguish
433→	// real user prompts from tool_result messages (both have type "user").
434→	lines, err := transcript.ParseFromBytes(data)
435→	if err == nil {
436→		count := 0
437→		for _, line := range lines {
438→			if line.Type == transcript.TypeUser {
439→				if transcript.ExtractUserContent(line.Message) != "" {
440→					count++
441→				}
442→			}
443→		}
444→		if count > 0 {
445→			return count
446→		}
447→	}
448→
449→	// Fallback: Gemini JSON format
450→	if prompts, gemErr := geminicli.ExtractAllUserPrompts(data); gemErr == nil {
451→		return len(prompts)
452→	}
453→
454→	return 0
455→}
456→
457→// extractModelFromTranscript extracts the model name from a JSONL transcript.
458→// Best-effort: returns empty string if the transcript format doesn't include model info
459→// (e.g., Gemini stores model info in hook events, not the transcript).
460→func extractModelFromTranscript(data []byte) string {
461→	lines, err := transcript.ParseFromBytes(data)
462→	if err != nil {
463→		return ""
464→	}
465→
466→	for _, line := range lines {
467→		if line.Type != transcript.TypeAssistant {
468→			continue
469→		}
470→		var msg struct {
471→			Model string `json:"model"`
472→		}
473→		if err := json.Unmarshal(line.Message, &msg); err == nil && msg.Model != "" {
474→			return msg.Model
475→		}
476→	}
477→	return ""
478→}
479→
480→// estimateSessionDuration estimates session duration in milliseconds from JSONL transcript timestamps.
481→// The "timestamp" field is a top-level field in JSONL lines (alongside "type", "uuid", "message"),
482→// NOT inside the "message" object. We parse raw lines since transcript.Line doesn't capture it.
483→// Returns 0 if timestamps are not available (e.g., Gemini transcripts).
484→func estimateSessionDuration(data []byte) int64 {
485→	type timestamped struct {
486→		Timestamp string `json:"timestamp"`
487→	}
488→
489→	var first, last time.Time
490→	for _, rawLine := range bytes.Split(data, []byte("\n")) {
491→		if len(rawLine) == 0 {
492→			continue
493→		}
494→		var ts timestamped
495→		if err := json.Unmarshal(rawLine, &ts); err != nil || ts.Timestamp == "" {
496→			continue
497→		}
498→		parsed, err := time.Parse(time.RFC3339Nano, ts.Timestamp)
499→		if err != nil {
500→			parsed, err = time.Parse(time.RFC3339, ts.Timestamp)
501→			if err != nil {
502→				continue
503→			}
504→		}
505→		if first.IsZero() {
506→			first = parsed
507→		}
508→		last = parsed
509→	}
510→
511→	if first.IsZero() || last.IsZero() || !last.After(first) {
512→		return 0
513→	}
514→	return last.Sub(first).Milliseconds()
515→}
